const express = require('express');
const { SQSClient, SendMessageBatchCommand } = require('@aws-sdk/client-sqs');
const { SnapshotRepository } = require('../repositories/snapshots');

const app = express();
app.use(express.json());

const sqs = new SQSClient({ region: 'us-west-2' });
const PURGE_QUEUE_URL = process.env.BACKUP_PURGE_SQS_URL;

app.post('/api/storage/backups/batch-purge', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Tenant authentication required' });
  }

  const { snapshotIds } = req.body;

  if (!Array.isArray(snapshotIds) || snapshotIds.length === 0) {
    return res.status(400).json({ error: 'snapshotIds array is required' });
  }

  // Validate that all requested snapshots belong to the authenticated caller's tenant
  const ownedSnapshots = await SnapshotRepository.findAllByIdsAndTenant(
    snapshotIds.slice(0, 10),
    req.user.tenantId
  );

  const ownedIds = new Set(ownedSnapshots.map(s => s.id));
  const unauthorizedIds = snapshotIds.slice(0, 10).filter(id => !ownedIds.has(id));

  if (unauthorizedIds.length > 0) {
    return res.status(403).json({
      error: 'Access denied: one or more snapshots belong to another tenant',
      unauthorizedIds
    });
  }

  const entries = ownedSnapshots.map((snapshot, index) => ({
    Id: `msg_${index}`,
    MessageBody: JSON.stringify({
      action: 'PURGE_SNAPSHOT',
      snapshotId: snapshot.id,
      tenantId: req.user.tenantId,
      scheduledAt: Date.now()
    })
  }));

  const batchCmd = new SendMessageBatchCommand({
    QueueUrl: PURGE_QUEUE_URL,
    Entries: entries
  });

  try {
    const response = await sqs.send(batchCmd);
    res.json({
      successful: response.Successful || [],
      failed: response.Failed || []
    });
  } catch (err) {
    res.status(500).json({ error: 'Failed to enqueue purge batch' });
  }
});

app.listen(3002);
